47	    int64_t ubSizeLimit = static_cast<int64_t>(ubSize);
48	
49	    // ---- Block level tiling (inter-core, Cache Line aligned) ----
50	    int64_t totalLengthCore = (totalLength + coreNum - 1) / coreNum;
51	    int64_t totalLengthCoreAlign = (totalLengthCore + CACHE_LINE_BYTE_LENGTH - 1)
52	                                    / CACHE_LINE_BYTE_LENGTH * CACHE_LINE_BYTE_LENGTH;
53	
54	    int64_t usedCoreNum = (totalLength + totalLengthCoreAlign - 1) / totalLengthCoreAlign;
55	    int64_t formerNum = usedCoreNum - 1;
56	    int64_t formerLength = totalLengthCoreAlign;
57	    int64_t tailLength = totalLength - formerNum * formerLength;
58	
59	    // ---- UB level tiling (intra-core) ----
60	    // bufferCoefficient: inQueueX(BUFFER_NUM) + outQueueY(BUFFER_NUM) + tmpBuf(1 for fp16/bf16)
61	    // For fp16/bf16: 2*2 + 2*2 + 4 = 12 bytes per element (but we use float tmpBuf)
62	    // Simplified: for all dtypes, use coefficient based on dtypeSize
63	    int64_t bufferCoefficient;
64	    if (dtypeSize == 2) {
65	        // fp16/bf16: inQueue(2*2) + outQueue(2*2) + tmpBuf(4) = 12 -> round to 16 for safety
66	        bufferCoefficient = 16;
67	    } else {
68	        // fp32/int32: inQueue(2*4) + outQueue(2*4) = 16
69	        bufferCoefficient = 16;
70	    }
71	
72	    int64_t maxTileElements = ubSizeLimit / bufferCoefficient;
73	    int64_t alignElements = 32 / dtypeSize;
74	    int64_t tileLength = (maxTileElements / alignElements) * alignElements;
75	    if (tileLength == 0) {
76	        tileLength = alignElements;
77	    }
78	
79	    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);
80	
81	    // ---- Prepare scalar and offset data on device ----
82	    // We need to pass scalar values and tensor offsets to the kernel
