97	    if (scalarCpu.scalar_type() == at::kFloat) {
98	        float *src = scalarCpu.data_ptr<float>();
99	        for (int64_t i = 0; i < tensorNum && i < MAX_TENSOR_NUM; ++i) {
100	            scalarPtr[i] = src[i];
101	        }
102	    } else if (scalarCpu.scalar_type() == at::kInt) {
103	        int32_t *src = scalarCpu.data_ptr<int32_t>();
104	        for (int64_t i = 0; i < tensorNum && i < MAX_TENSOR_NUM; ++i) {
105	            scalarPtr[i] = static_cast<float>(src[i]);
106	        }
107	    }
108	
