10	
11	#include "kernel_operator.h"
12	
13	constexpr int32_t BUFFER_NUM = 2;
14	constexpr int32_t MAX_TENSOR_NUM = 16;
15	
16	template <typename T>
17	class KernelForeachMulScalarList {
18	public:
19	    __aicore__ inline KernelForeachMulScalarList() {}
20	
21	    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y, GM_ADDR scalar,
22	                                int64_t tensorNum,
23	                                int64_t formerNum, int64_t formerLength,
24	                                int64_t tailLength, int64_t tileLength,
25	                                int64_t totalLength)
26	    {
27	        int64_t blockIdx = AscendC::GetBlockIdx();
28	
29	        this->tensorNum = tensorNum;
30	        this->totalLength = totalLength;
31	        this->tileLength = tileLength;
32	
33	        // Read scalar values from GM
34	        __gm__ float *scalarGm = (__gm__ float *)scalar;
35	        for (int64_t i = 0; i < tensorNum && i < MAX_TENSOR_NUM; ++i) {
36	            scalarValues[i] = scalarGm[i];
37	        }
38	
39	        // Read tensor offsets from GM (after scalar values)
40	        __gm__ int64_t *offsetGm = (__gm__ int64_t *)(scalar + MAX_TENSOR_NUM * sizeof(float));
41	        for (int64_t i = 0; i < tensorNum && i < MAX_TENSOR_NUM; ++i) {
42	            tensorOffsets[i] = offsetGm[i];
43	        }
44	
45	        if (blockIdx < formerNum) {
46	            this->blockLength = formerLength;
47	            int64_t offset = formerLength * blockIdx;
48	            xGm.SetGlobalBuffer((__gm__ T *)x + offset, formerLength);
49	            yGm.SetGlobalBuffer((__gm__ T *)y + offset, formerLength);
50	            this->globalOffset = offset;
51	        } else {
52	            this->blockLength = tailLength;
53	            int64_t tailIdx = blockIdx - formerNum;
54	            int64_t offset = formerLength * formerNum + tailLength * tailIdx;
55	            xGm.SetGlobalBuffer((__gm__ T *)x + offset, tailLength);
56	            yGm.SetGlobalBuffer((__gm__ T *)y + offset, tailLength);
57	            this->globalOffset = offset;
58	        }
59	
60	        pipe.InitBuffer(inQueueX, BUFFER_NUM, tileLength * sizeof(T));
61	        pipe.InitBuffer(outQueueY, BUFFER_NUM, tileLength * sizeof(T));
62	        if constexpr (sizeof(T) == sizeof(half)) {
63	            pipe.InitBuffer(tmpBuf, tileLength * sizeof(float));
64	        }
65	    }
66	
67	    __aicore__ inline void Process()
68	    {
69	        int64_t tileNum = (this->blockLength + this->tileLength - 1) / this->tileLength;
70	        int64_t tailTileLength = this->blockLength - (tileNum - 1) * this->tileLength;
71	
72	        int64_t alignNum = 32 / static_cast<int64_t>(sizeof(T));
73	        int64_t alignedTailLen = ((tailTileLength + alignNum - 1) / alignNum) * alignNum;
74	
75	        for (int64_t i = 0; i < tileNum - 1; ++i) {
76	            CopyIn(i, this->tileLength);
77	            Compute(i, this->tileLength);
78	            CopyOut(i, this->tileLength);
79	        }
80	        if (tileNum > 0) {
81	            CopyIn(tileNum - 1, alignedTailLen);
82	            Compute(tileNum - 1, alignedTailLen);
83	            CopyOut(tileNum - 1, alignedTailLen);
84	        }
85	    }
86	
87	private:
88	    __aicore__ inline void CopyIn(int64_t progress, int64_t curTileLength)
89	    {
90	        AscendC::LocalTensor<T> xLocal = inQueueX.AllocTensor<T>();
91	        AscendC::DataCopyPadExtParams<T> padParams{false, 0, 0, 0};
92	        AscendC::DataCopyExtParams copyParams{1, static_cast<uint32_t>(curTileLength * sizeof(T)), 0, 0, 0};
93	        AscendC::DataCopyPad(xLocal, xGm[progress * this->tileLength], copyParams, padParams);
94	        inQueueX.EnQue(xLocal);
95	    }
96	
97	    __aicore__ inline float GetScalarValue(int64_t globalIdx)
98	    {
99	        for (int64_t i = tensorNum - 1; i >= 0; --i) {
100	            if (globalIdx >= tensorOffsets[i]) {
101	                return scalarValues[i];
102	            }
103	        }
104	        return scalarValues[0];
105	    }
106	
107	    __aicore__ inline void Compute(int64_t progress, int64_t curTileLength)
108	    {
109	        AscendC::LocalTensor<T> xLocal = inQueueX.DeQue<T>();
110	        AscendC::LocalTensor<T> yLocal = outQueueY.AllocTensor<T>();
111	
112	        int64_t tileGlobalStart = this->globalOffset + progress * this->tileLength;
113	
114	        if constexpr (sizeof(T) == sizeof(float)) {
115	            // FP32 / INT32 direct compute
116	            // Process in segments where each segment has the same scalar
117	            int64_t pos = 0;
118	            while (pos < curTileLength) {
119	                int64_t globalIdx = tileGlobalStart + pos;
120	                float scalarVal = GetScalarValue(globalIdx);
121	
122	                // Find the end of this segment (same scalar)
123	                int64_t tensorIdx = 0;
124	                for (int64_t i = tensorNum - 1; i >= 0; --i) {
125	                    if (globalIdx >= tensorOffsets[i]) {
126	                        tensorIdx = i;
127	                        break;
128	                    }
129	                }
130	                int64_t tensorEnd = (tensorIdx < tensorNum - 1) ? tensorOffsets[tensorIdx + 1] : totalLength;
131	                int64_t segmentLen = tensorEnd - globalIdx;
132	                if (segmentLen > curTileLength - pos) {
133	                    segmentLen = curTileLength - pos;
134	                }
135	
136	                if constexpr (std::is_same_v<T, int32_t>) {
137	                    // For int32, scalar is int, use direct multiply
