11	#include "torch_kernel_helper.h"
12	#include "tiling/platform/platform_ascendc.h"
13	#include "aclrtlaunch_ForeachMulScalarList.h"
14	
15	#include <vector>
16	
17	namespace ascend_kernel {
18	
19	constexpr int64_t CACHE_LINE_BYTE_LENGTH = 512;
20	
21	at::Tensor ForeachMulScalarList(const at::Tensor &input,
22	                                const at::Tensor &scalar,
23	                                const at::Tensor &offsets,
24	                                int64_t tensorNum)
25	{
26	    TORCH_CHECK(input.is_contiguous(), "ForeachMulScalarList: input must be contiguous");
27	    TORCH_CHECK(scalar.dim() == 1, "ForeachMulScalarList: scalar must be 1D tensor");
28	    TORCH_CHECK(offsets.dim() == 1, "ForeachMulScalarList: offsets must be 1D tensor");
29	    TORCH_CHECK(tensorNum > 0, "ForeachMulScalarList: tensorNum must be > 0");
30	
31	    at::Tensor output = at::empty_like(input);
32	
33	    int64_t totalLength = input.numel();
34	    if (totalLength == 0) {
35	        return output;
36	    }
37	
38	    int64_t dtypeSize = input.element_size();
39	
40	    // ---- Get hardware params ----
41	    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
42	    int64_t coreNum = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());
43	    uint64_t ubSize;
44	    ascendc_platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
45	    int64_t ubSizeLimit = static_cast<int64_t>(ubSize);
46	
47	    // ---- Block level tiling (inter-core, Cache Line aligned) ----
48	    int64_t totalLengthCore = (totalLength + coreNum - 1) / coreNum;
49	    int64_t totalLengthCoreAlign = (totalLengthCore + CACHE_LINE_BYTE_LENGTH - 1)
50	                                    / CACHE_LINE_BYTE_LENGTH * CACHE_LINE_BYTE_LENGTH;
51	
52	    int64_t usedCoreNum = (totalLength + totalLengthCoreAlign - 1) / totalLengthCoreAlign;
53	    int64_t formerNum = usedCoreNum - 1;
54	    int64_t formerLength = totalLengthCoreAlign;
55	    int64_t tailLength = totalLength - formerNum * formerLength;
56	
57	    // ---- UB level tiling (intra-core) ----
58	    int64_t bufferCoefficient = 16;
59	    int64_t maxTileElements = ubSizeLimit / bufferCoefficient;
60	    int64_t alignElements = 32 / dtypeSize;
61	    if (alignElements == 0) alignElements = 1;
62	    int64_t tileLength = (maxTileElements / alignElements) * alignElements;
63	    if (tileLength == 0) {
64	        tileLength = alignElements;
65	    }
66	
67	    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);
68	
69	    // Ensure scalar and offsets are on device and contiguous
70	    at::Tensor scalarDev = scalar.to(input.device()).contiguous();
71	    at::Tensor offsetsDev = offsets.to(input.device()).contiguous();
72	
73	    // EXEC_KERNEL_CMD: all params must be lvalues
74	    int64_t tensorNumL = tensorNum;
75	    int64_t formerNumL = formerNum;
76	    int64_t formerLengthL = formerLength;
77	    int64_t tailLengthL = tailLength;
78	    int64_t tileLengthL = tileLength;
79	    int64_t totalLengthL = totalLength;
80	    int64_t dtypeSizeL = dtypeSize;
81	
82	    EXEC_KERNEL_CMD(ForeachMulScalarList, blockDim,
83	                    input, output, scalarDev, offsetsDev,
84	                    tensorNumL, formerNumL, formerLengthL, tailLengthL, tileLengthL,
85	                    totalLengthL, dtypeSizeL);
86	
87	    return output;
88	}
89	
90	}  // namespace ascend_kernel
