#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"
#include "aclrtlaunch_ForeachMulScalarList.h"

#include <vector>

namespace ascend_kernel {

constexpr int64_t CACHE_LINE_BYTE_LENGTH = 512;

at::Tensor ForeachMulScalarList(const at::Tensor &input,
                                const at::Tensor &scalar,
                                const at::Tensor &offsets,
                                int64_t tensorNum)
{
    TORCH_CHECK(input.is_contiguous(), "ForeachMulScalarList: input must be contiguous");
    TORCH_CHECK(scalar.dim() == 1, "ForeachMulScalarList: scalar must be 1D tensor");
    TORCH_CHECK(offsets.dim() == 1, "ForeachMulScalarList: offsets must be 1D tensor");
    TORCH_CHECK(tensorNum > 0, "ForeachMulScalarList: tensorNum must be > 0");

    at::Tensor output = at::empty_like(input);

    int64_t totalLength = input.numel();
    if (totalLength == 0) {
        return output;
    }

    int64_t dtypeSize = input.element_size();

    // Determine dtype enum: 0=half, 1=float, 2=bfloat16, 3=int32
    int64_t dtypeEnum = 0;
    if (input.scalar_type() == at::kFloat) {
        dtypeEnum = 1;
    } else if (input.scalar_type() == at::kBFloat16) {
        dtypeEnum = 2;
    } else if (input.scalar_type() == at::kInt) {
        dtypeEnum = 3;
    }

    // ---- Get hardware params ----
    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());
    uint64_t ubSize;
    ascendc_platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
    int64_t ubSizeLimit = static_cast<int64_t>(ubSize);

    // ---- Block level tiling (inter-core, Cache Line aligned) ----
    int64_t totalLengthCore = (totalLength + coreNum - 1) / coreNum;
    int64_t totalLengthCoreAlign = (totalLengthCore + CACHE_LINE_BYTE_LENGTH - 1)
                                    / CACHE_LINE_BYTE_LENGTH * CACHE_LINE_BYTE_LENGTH;

    int64_t usedCoreNum = (totalLength + totalLengthCoreAlign - 1) / totalLengthCoreAlign;
    int64_t formerNum = usedCoreNum - 1;
    int64_t formerLength = totalLengthCoreAlign;
    int64_t tailLength = totalLength - formerNum * formerLength;

    // ---- UB level tiling (intra-core) ----
    int64_t bufferCoefficient = 16;
    int64_t maxTileElements = ubSizeLimit / bufferCoefficient;
    int64_t alignElements = 32 / dtypeSize;
    if (alignElements == 0) alignElements = 1;
    int64_t tileLength = (maxTileElements / alignElements) * alignElements;
    if (tileLength == 0) {
        tileLength = alignElements;
    }

    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);

    // Ensure scalar and offsets are on device and contiguous
    at::Tensor scalarDev = scalar.to(input.device()).contiguous();
    at::Tensor offsetsDev = offsets.to(input.device()).contiguous();

    // EXEC_KERNEL_CMD: all params must be lvalues
    int64_t tensorNumL = tensorNum;
    int64_t formerNumL = formerNum;
    int64_t formerLengthL = formerLength;
    int64_t tailLengthL = tailLength;
    int64_t tileLengthL = tileLength;
    int64_t totalLengthL = totalLength;
    int64_t dtypeSizeL = dtypeSize;
    int64_t dtypeEnumL = dtypeEnum;

    EXEC_KERNEL_CMD(ForeachMulScalarList, blockDim,
                    input, output, scalarDev, offsetsDev,
                    tensorNumL, formerNumL, formerLengthL, tailLengthL, tileLengthL,
                    totalLengthL, dtypeSizeL, dtypeEnumL);

    return output;
}

}  // namespace ascend_kernel
